"""An in-memory account store."""

import uuid

_ACCOUNTS: dict[str, dict] = {}


def create_account(name):
    """Store a new account and return its id."""
    account_id = str(uuid.uuid4())
    _ACCOUNTS[account_id] = {"account_id": account_id, "name": name}
    return account_id


def read_account(account_id):
    """Return one account, or None when there is no such account."""
    return _ACCOUNTS.get(account_id)


def update_account(account_id, name):
    """Rename an account. Return the updated account, or None."""
    account = _ACCOUNTS.get(account_id)
    if account is None:
        return None
    account["name"] = name
    return account


def delete_account(account_id):
    """Remove an account. Return True when one was removed."""
    # TODO: deleting an account must decide what happens to whatever belongs to it
    return _ACCOUNTS.pop(account_id, None) is not None


def list_accounts():
    """Return every stored account, in insertion order."""
    return list(_ACCOUNTS.values())

