"""An in-memory commercial client store."""

import uuid

_COMMERCIAL_CLIENTS: dict[str, dict] = {}


def create_commercial_client(account_id):
    """Store a new commercial client under one account and return its id."""
    commercial_client_id = str(uuid.uuid4())
    _COMMERCIAL_CLIENTS[commercial_client_id] = {
        "commercial_client_id": commercial_client_id,
        "account_id": account_id,
    }
    return commercial_client_id


def read_commercial_client(commercial_client_id):
    """Return one commercial client, or None when there is no such commercial client."""
    return _COMMERCIAL_CLIENTS.get(commercial_client_id)

